def _skip_by_extension(path: str) -> bool:
    name_lower = os.path.basename(path).lower()
    if name_lower in INTERESTING_FILES:
        return False
    _, ext = os.path.splitext(name_lower)
    if ext in BINARY_EXTENSIONS:
        return True
    if not ext:
        return True
    return ext not in TEXT_EXTENSIONS


def _is_binary(path: str) -> bool:
    try:
        with open(path, "rb") as f:
            chunk = f.read(8192)
            return b"\x00" in chunk
    except OSError:
        return True


class _ExcludeMatcher:
    """Fast exclude matcher optimized for the common `**/<name>/**` pattern."""

    def __init__(self, globs: list[str]) -> None:
        self._dir_names: set[str] = set()
        self._subpath_parts: list[list[str]] = []

        for g in globs:
            stripped = g
            if stripped.startswith("**/"):
                stripped = stripped[3:]
            if stripped.endswith("/**"):
                stripped = stripped[:-3]

            if g.startswith("**/") and g.endswith("/**"):
                if "/" not in stripped and "*" not in stripped and "?" not in stripped:
                    self._dir_names.add(stripped)
                else:
                    self._subpath_parts.append(stripped.split("/"))

    def should_prune_dir(self, dir_name: str, dir_path_parts: list[str]) -> bool:
        if dir_name in self._dir_names:
            return True
        for parts in self._subpath_parts:
            plen = len(parts)
            for i in range(len(dir_path_parts) - plen + 1):
                if dir_path_parts[i:i + plen] == parts:
                    return True
        return False


def _scan_file(
    path: str,
    rules: list[CompiledRule],
    reveal_length: bool,
    allow_matcher: Callable[[str], bool] | None,
) -> list[Finding]:
    findings: list[Finding] = []
    try:
        with open(path, "rb") as fb:
            head = fb.read(512)
            if b"\x00" in head:
                return findings
            fb.seek(0)
            raw = fb.read()
    except OSError:
        return findings
    text = raw.decode("utf-8", errors="replace")
    lines = [l.rstrip("\n\r") for l in text.split("\n")]
    scan_lines(
        lines,
        rules,
        path,
        Module.FILESYSTEM,
        findings.append,
        reveal_length=reveal_length,
        allow_matcher=allow_matcher,
    )
    return findings


def filesystem_scan(
    cfg: Config,
    rules: list[CompiledRule],
    emit: Callable[[Finding], None],
    allow_matcher: Callable[[str], bool] | None = None,
) -> ModuleStatus:
    status = ModuleStatus(module=Module.FILESYSTEM)
    matcher = _ExcludeMatcher(cfg.effective_excludes())
    concurrency = cfg.concurrency if cfg.concurrency > 0 else os.cpu_count() or 4
    max_size = cfg.max_file_size

    file_paths: list[str] = []
    for root_path in cfg.paths:
        for dirpath, dirnames, filenames in os.walk(root_path, followlinks=False):
            path_parts = dirpath.split(os.sep)

            new_dirs = []
            for d in dirnames:
                if d.startswith(".Trash"):
                    continue
                _, ext = os.path.splitext(d)
                if ext in BUNDLE_DIR_EXTENSIONS:
                    continue
                child_parts = path_parts + [d]
                if matcher.should_prune_dir(d, child_parts):
                    continue
                new_dirs.append(d)
            dirnames[:] = new_dirs

            for fname in filenames:
                if _skip_by_extension(fname):
                    continue
                fpath = os.path.join(dirpath, fname)
                try:
                    st = os.lstat(fpath)
                except OSError:
                    continue
                if not (st.st_mode & 0o100000):
                    continue
                if st.st_size > max_size or st.st_size == 0:
                    continue
                file_paths.append(fpath)

    status.attempted = len(file_paths)

    from secretscan.rules.loader import load_default_rules, load_rules_file
    rules_file = cfg.rules_file

    CHUNK = 500
    chunks = [file_paths[i:i + CHUNK] for i in range(0, len(file_paths), CHUNK)]

    with ProcessPoolExecutor(max_workers=concurrency) as pool:
        futures = {
            pool.submit(_scan_chunk, chunk, rules_file, cfg.reveal_length): chunk
            for chunk in chunks
        }
        for future in as_completed(futures):
            try:
                results = future.result()
            except Exception:
                status.skipped += len(futures[future])
                continue
            for f in results:
                emit(f)
            status.accessed += len(futures[future])

    status.skipped = status.attempted - status.accessed
    return status


def _scan_chunk(
    paths: list[str],
    rules_file: str,
    reveal_length: bool,
) -> list[Finding]:
    from secretscan.rules.loader import load_default_rules, load_rules_file
    if rules_file:
        rules = load_rules_file(rules_file)
    else:
        rules = load_default_rules()

    all_findings: list[Finding] = []
    for path in paths:
        all_findings.extend(_scan_file(path, rules, reveal_length, None))
    return all_findings
